/// Some Arrow IPC array types carry metadata (view structs) that arrow's cheap structural
/// validation does not fully check. For these types we additionally run full validation,
/// which verifies each view's internal length/offset/size against the variadic data buffers.
/// This is safe to run unconditionally because ClickHouse never produces view arrays itself,
/// so a well-formed view column would simply be reported as an unsupported type later on.
bool arrowTypeNeedsFullValidation(const arrow::DataType & type)
{
    switch (type.id())
    {
        case arrow::Type::STRING_VIEW:
        case arrow::Type::BINARY_VIEW:
            return true;
        default:
            return false;
    }
}

void fullyValidateViewArrays(const std::shared_ptr<arrow::ArrayData> & data, const std::string & column_name)
{
    if (!data || !data->type)
        return;

    if (arrowTypeNeedsFullValidation(*data->type))
    {
        auto array = arrow::MakeArray(data);
        auto status = array->ValidateFull();
        if (!status.ok())
            throw Exception(
                ErrorCodes::INCORRECT_DATA,
                "Arrow data for column '{}' is corrupted: {}",
                column_name,
                status.ToString());
    }

    for (const auto & child : data->child_data)
        fullyValidateViewArrays(child, column_name);
    fullyValidateViewArrays(data->dictionary, column_name);
}

/// Validate a record batch decoded from a (possibly malicious) Arrow IPC stream before it is
/// used to build an Arrow table and converted to ClickHouse columns.
///
/// The Arrow IPC reader trusts the declared FieldNode lengths/null counts and does not check
/// them against the actual sizes of the decoded buffers, so a crafted file can declare far more
/// rows than a buffer can hold and trigger heap out-of-bounds reads (either directly in the
/// column readers, or inside Arrow itself when it lazily computes null counts by scanning the
/// validity bitmap over the declared length).
///
/// arrow::RecordBatch::Validate() performs exactly the structural checks we need: it verifies
/// that every buffer (validity bitmap, fixed-width values, offsets, view structs, ...) is large
/// enough for the declared length and offset, checks list/struct/map child lengths and offset
/// bounds, and rejects negative/overflowing lengths — all without scanning the data (so it
/// cannot itself read out of bounds, and it does not reject otherwise-valid data such as
/// non-UTF8 bytes in utf8 columns). We run it before arrow::Table::FromRecordBatches() and
/// before any column memory is reserved.
void validateArrowRecordBatch(const arrow::RecordBatch & batch)
{
    auto status = batch.Validate();
    if (!status.ok())
        throw Exception(
            ErrorCodes::INCORRECT_DATA,
            "Arrow record batch is corrupted: {}",
            status.ToString());

    for (int i = 0; i < batch.num_columns(); ++i)
        fullyValidateViewArrays(batch.column(i)->data(), batch.column_name(i));
}

